import React, { useState, useEffect, useRef } from 'react'
import './DataDashboard.css'

// Static stats file path (generated by scripts/generate-dashboard-stats.mjs)
const STATS_URL = '/data/dashboard-stats.json'

// Animated counter hook - counts up from 0 to target value
function useAnimatedCounter(target, duration = 1000) {
  const [count, setCount] = useState(0)
  const startTimeRef = useRef(null)
  const rafRef = useRef(null)

  useEffect(() => {
    if (typeof target !== 'number' || target === 0) {
      setCount(target || 0)
      return
    }

    startTimeRef.current = performance.now()

    const animate = (currentTime) => {
      const elapsed = currentTime - startTimeRef.current
      const progress = Math.min(elapsed / duration, 1)

      // Ease out cubic for smooth deceleration
      const eased = 1 - Math.pow(1 - progress, 3)
      setCount(Math.floor(eased * target))

      if (progress < 1) {
        rafRef.current = requestAnimationFrame(animate)
      } else {
        setCount(target)
      }
    }

    rafRef.current = requestAnimationFrame(animate)

    return () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current)
      }
    }
  }, [target, duration])

  return count
}
// Stat Card Component with animated counter
function StatCard({ label, value, subtext, accent }) {
  const animatedValue = useAnimatedCounter(typeof value === 'number' ? value : 0, 1200)
  const displayValue = typeof value === 'number' ? animatedValue.toLocaleString() : value

  return (
    <div className="stat-card" style={accent ? { '--card-accent': accent } : undefined}>
      <div className="stat-value">{displayValue}</div>
      <div className="stat-label">{label}</div>
      {subtext && <div className="stat-subtext">{subtext}</div>}
    </div>
  )
}

// Bar Chart Component with animated bars
function BarChart({ data, maxValue, accentColor, showPercent }) {
  const [animated, setAnimated] = useState(false)
  const max = maxValue || Math.max(...data.map(d => d[1]))

  useEffect(() => {
    // Trigger animation after mount
    const timer = setTimeout(() => setAnimated(true), 50)
    return () => clearTimeout(timer)
  }, [])

  return (
    <div className="bar-chart">
      {data.map(([label, count], index) => (
        <div key={label} className="bar-row" style={{ '--bar-delay': `${index * 80}ms` }}>
          <span className="bar-label">{label}</span>
          <div className="bar-track">
            <div
              className={`bar-fill ${animated ? 'animated' : ''}`}
              style={{
                '--bar-width': `${(count / max) * 100}%`,
                background: accentColor || 'var(--app-accent)',
              }}
            />
          </div>
          <span className="bar-value">
            {count.toLocaleString()}
            {showPercent && <span className="bar-percent"> ({((count / max) * 100).toFixed(0)}%)</span>}
          </span>
        </div>
      ))}
    </div>
  )
}

// Status Breakdown Component with animated segments
function StatusBreakdown({ visited, unvisited, golden, total }) {
  const [animated, setAnimated] = useState(false)
  const pctVisited = total ? ((visited / total) * 100).toFixed(1) : 0
  const pctUnvisited = total ? ((unvisited / total) * 100).toFixed(1) : 0
  const pctGolden = total ? ((golden / total) * 100).toFixed(1) : 0

  const animatedVisited = useAnimatedCounter(visited, 1200)
  const animatedGolden = useAnimatedCounter(golden, 1200)
  const animatedUnvisited = useAnimatedCounter(unvisited, 1200)

  useEffect(() => {
    const timer = setTimeout(() => setAnimated(true), 50)
    return () => clearTimeout(timer)
  }, [])

  return (
    <div className="status-breakdown">
      <div className="status-bar">
        <div
          className={`status-segment visited ${animated ? 'animated' : ''}`}
          style={{ '--segment-width': `${pctVisited}%` }}
          title={`Visited: ${pctVisited}%`}
        />
        <div
          className={`status-segment golden ${animated ? 'animated' : ''}`}
          style={{ '--segment-width': `${pctGolden}%`, '--segment-delay': '150ms' }}
          title={`Golden: ${pctGolden}%`}
        />
        <div
          className={`status-segment unvisited ${animated ? 'animated' : ''}`}
          style={{ '--segment-width': `${pctUnvisited}%`, '--segment-delay': '300ms' }}
          title={`Unvisited: ${pctUnvisited}%`}
        />
      </div>
      <div className="status-legend">
        <span className="legend-item"><span className="dot visited" /> Visited ({animatedVisited.toLocaleString()})</span>
        <span className="legend-item"><span className="dot golden" /> Golden ({animatedGolden.toLocaleString()})</span>
        <span className="legend-item"><span className="dot unvisited" /> Unvisited ({animatedUnvisited.toLocaleString()})</span>
      </div>
    </div>
  )
}

// Data Quality Card Component
function DataQualityCard({ label, value, total, color }) {
  const [animated, setAnimated] = useState(false)
  const pct = total ? ((value / total) * 100) : 0
  const animatedValue = useAnimatedCounter(value, 1200)

  useEffect(() => {
    const timer = setTimeout(() => setAnimated(true), 50)
    return () => clearTimeout(timer)
  }, [])

  return (
    <div className="quality-card">
      <div className="quality-label">{label}</div>
      <div className="quality-bar-track">
        <div
          className={`quality-bar-fill ${animated ? 'animated' : ''}`}
          style={{ '--bar-width': `${pct}%`, background: color }}
        />
      </div>
      <div className="quality-value">
        {pct.toFixed(1)}% <span className="quality-count">({animatedValue.toLocaleString()} / {total.toLocaleString()})</span>
      </div>
    </div>
  )
}

// Rating Stat Card (shows average with star)
function RatingStatCard({ avgRating, ratedCount, accent }) {
  const [displayRating, setDisplayRating] = useState(0)

  useEffect(() => {
    if (avgRating === null) return
    const duration = 1200
    const startTime = performance.now()
    let rafId

    const animate = (currentTime) => {
      const elapsed = currentTime - startTime
      const progress = Math.min(elapsed / duration, 1)
      const eased = 1 - Math.pow(1 - progress, 3)
      setDisplayRating(eased * avgRating)

      if (progress < 1) {
        rafId = requestAnimationFrame(animate)
      } else {
        setDisplayRating(avgRating)
      }
    }

    rafId = requestAnimationFrame(animate)
    return () => cancelAnimationFrame(rafId)
  }, [avgRating])

  if (avgRating === null) {
    return (
      <div className="stat-card" style={accent ? { '--card-accent': accent } : undefined}>
        <div className="stat-value">-</div>
        <div className="stat-label">Avg Rating</div>
        <div className="stat-subtext">No ratings yet</div>
      </div>
    )
  }

  return (
    <div className="stat-card" style={accent ? { '--card-accent': accent } : undefined}>
      <div className="stat-value rating-value">
        <span className="rating-star">★</span> {displayRating.toFixed(1)}
      </div>
      <div className="stat-label">Avg Rating</div>
      <div className="stat-subtext">from {ratedCount.toLocaleString()} rated</div>
    </div>
  )
}

// Best Rated Styles Component
function BestRatedStyles({ styles, accentColor }) {
  const [animated, setAnimated] = useState(false)

  useEffect(() => {
    const timer = setTimeout(() => setAnimated(true), 50)
    return () => clearTimeout(timer)
  }, [])

  if (!styles.length) {
    return <p className="no-data">Not enough rated places by style yet</p>
  }

  return (
    <div className="best-rated-list">
      {styles.map(([style, avgRating, count], index) => (
        <div key={style} className="best-rated-item" style={{ '--item-delay': `${index * 100}ms` }}>
          <span className="best-rated-rank">#{index + 1}</span>
          <span className="best-rated-style">{style}</span>
          <span className={`best-rated-rating ${animated ? 'animated' : ''}`}>
            <span className="rating-star">★</span> {avgRating.toFixed(2)}
          </span>
          <span className="best-rated-count">({count} places)</span>
        </div>
      ))}
    </div>
  )
}

// Best Rated Regions Component (similar to BestRatedStyles but for regions)
function BestRatedRegions({ regions, accentColor }) {
  const [animated, setAnimated] = useState(false)

  useEffect(() => {
    const timer = setTimeout(() => setAnimated(true), 50)
    return () => clearTimeout(timer)
  }, [])

  if (!regions.length) {
    return <p className="no-data">Not enough rated regions yet (min 10 places)</p>
  }

  return (
    <div className="best-rated-list">
      {regions.map(([region, avgRating, count], index) => (
        <div key={region} className="best-rated-item" style={{ '--item-delay': `${index * 80}ms` }}>
          <span className="best-rated-rank">#{index + 1}</span>
          <span className="best-rated-style">{region}</span>
          <span className={`best-rated-rating ${animated ? 'animated' : ''}`}>
            {avgRating.toFixed(1)}/10
          </span>
          <span className="best-rated-count">({count} rated)</span>
        </div>
      ))}
    </div>
  )
}

