// Main Dashboard Component
export default function DataDashboard() {
  const [activeTab, setActiveTab] = useState('overview')
  const [pizzaStats, setPizzaStats] = useState(null)
  const [tacoStats, setTacoStats] = useState(null)
  const [generatedAt, setGeneratedAt] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  useEffect(() => {
    async function loadStats() {
      setLoading(true)
      setError(null)

      try {
        // Load pre-computed stats from static JSON (zero egress!)
        const response = await fetch(STATS_URL)
        if (!response.ok) {
          throw new Error(`Failed to load stats: ${response.status}`)
        }

        const data = await response.json()
        setPizzaStats(data.pizza)
        setTacoStats(data.taco)
        setGeneratedAt(data.generatedAt)
      } catch (err) {
        console.error('Failed to load dashboard stats:', err)
        setError(err.message)
      } finally {
        setLoading(false)
      }
    }

    loadStats()
  }, [])

  if (loading) {
    return (
      <div className="data-dashboard">
        <div className="loading-state">
          <div className="spinner" />
          <p>Loading dashboard data...</p>
        </div>
      </div>
    )
  }

  if (error) {
    return (
      <div className="data-dashboard">
        <div className="error-state">
          <p>Failed to load data: {error}</p>
          <button onClick={() => window.location.reload()}>Retry</button>
        </div>
      </div>
    )
  }

  return (
    <div className="data-dashboard">
      <header className="dashboard-header">
        <h1>Data Dashboard</h1>
        <p className="dashboard-subtitle">Pizza and taco place statistics worldwide</p>
      </header>

      <nav className="dashboard-tabs">
        {['overview', 'pizza', 'taco'].map(tab => (
          <button
            key={tab}
            className={`dashboard-tab ${activeTab === tab ? 'active' : ''}`}
            onClick={() => setActiveTab(tab)}
          >
            {tab.charAt(0).toUpperCase() + tab.slice(1)}
          </button>
        ))}
      </nav>

      <main className="dashboard-content">
        {activeTab === 'overview' && <OverviewTab pizzaStats={pizzaStats} tacoStats={tacoStats} />}
        {activeTab === 'pizza' && <PizzaTab stats={pizzaStats} />}
        {activeTab === 'taco' && <TacoTab stats={tacoStats} />}
      </main>

      <footer className="dashboard-footer">
        <a href="/">Back to Map</a>
        {generatedAt && (
          <span className="stats-date">
            Stats updated: {new Date(generatedAt).toLocaleDateString()}
          </span>
        )}
      </footer>
    </div>
  )
}
